#ifndef SOIL_SENSOR_H
#define SOIL_SENSOR_H

#include <stdint.h>
#include "ipc.h"

#define GT_SOIL_I2C_ADDR 0x36    /* Adafruit STEMMA (seesaw) */

typedef struct gt_soil_sensor gt_soil_sensor;

/* i2c_dev: e.g. "/dev/i2c-1" */
gt_soil_sensor *gt_soil_open(const char *i2c_dev);
gt_status       gt_soil_read(gt_soil_sensor *s, uint32_t *raw_out);
void            gt_soil_close(gt_soil_sensor *s);

#endif
#ifndef LIGHT_SENSOR_H
#define LIGHT_SENSOR_H

#include <stdint.h>
#include "i2c_bus.h"
#include "ipc.h"

#define GT_LIGHT_I2C_ADDR 0x23   /* BH1750 */

/* BH1750 opcodes and timing (datasheet). */
#define GT_BH1750_POWER_DOWN   0x00
#define GT_BH1750_POWER_ON     0x01
#define GT_BH1750_RESET        0x07   /* clears data register; only valid while powered on */
#define GT_BH1750_CONT_HRES    0x10   /* continuous high-res mode, 1 lx/count */
#define GT_BH1750_MEAS_MAX_MS  180    /* worst-case high-res conversion time */
#define GT_LIGHT_RETRIES       3      /* extra read attempts after a failure */
#define GT_LIGHT_RETRY_GAP_MS  10

typedef struct gt_light_sensor gt_light_sensor;

/* Raw counts are what get stored; convert only for display/analysis. */
static inline double gt_light_raw_to_lux(uint32_t raw) { return raw / 1.2; }

/* i2c_dev: e.g. "/dev/i2c-1" */
gt_light_sensor *gt_light_open(const char *i2c_dev);
/* Takes ownership of `bus` (closed on failure or by gt_light_close). */
gt_light_sensor *gt_light_open_bus(gt_i2c_bus bus);
gt_status        gt_light_read(gt_light_sensor *s, uint32_t *raw_out);
void             gt_light_close(gt_light_sensor *s);

#endif
#ifndef I2C_BUS_H
#define I2C_BUS_H

#include <stddef.h>
#include <stdint.h>
#include "ipc.h"

/* Hardware seam: drivers talk to the bus only through these ops, so tests
 * can swap in a fake device instead of /dev/i2c-1. */
typedef struct {
    gt_status (*write)(void *ctx, const uint8_t *buf, size_t len);
    gt_status (*read)(void *ctx, uint8_t *buf, size_t len);   /* short read => GT_ERR_IO */
    void      (*sleep_ms)(void *ctx, uint32_t ms);             /* injectable so tests don't sleep */
    void      (*close)(void *ctx);
} gt_i2c_ops;

typedef struct {
    const gt_i2c_ops *ops;
    void             *ctx;
} gt_i2c_bus;

/* Linux impl: open(dev, O_RDWR) + ioctl(I2C_SLAVE, addr). dev: e.g. "/dev/i2c-1" */
gt_status gt_i2c_linux_open(const char *dev, uint8_t addr, gt_i2c_bus *out);

#endif
#ifndef SAMPLER_H
#define SAMPLER_H

#include <stdint.h>
#include "ipc.h"

/* Callbacks so the schedule can be tested without I2C hardware. */
typedef gt_status (*gt_read_fn)(void *ctx, uint32_t *raw_out);
typedef gt_status (*gt_emit_fn)(void *ctx, gt_sensor_id id, uint32_t raw);

typedef struct {
    gt_sensor_id id;
    uint32_t     period_ms;   /* 1000 light, 60000 soil */
    gt_read_fn   read;
    void        *read_ctx;
} gt_sampler_cfg;

typedef struct gt_sampler gt_sampler;

gt_sampler *gt_sampler_create(const gt_sampler_cfg *cfg, gt_emit_fn emit, void *emit_ctx);
/* One tick against a monotonic clock in ms; reads and emits if due. */
gt_status   gt_sampler_tick(gt_sampler *s, uint64_t now_ms);
void        gt_sampler_destroy(gt_sampler *s);

#endif
#ifndef SENSOR_HEALTH_H
#define SENSOR_HEALTH_H

#include <stdint.h>
#include "ipc.h"

/* Offline/online tracking for one sensor (DESIGN.md failure-mode table,
 * Sensor (I2C) row). Pure logic: the caller passes each read result and a
 * monotonic time in ms, and logs the returned transition. Times are
 * uint64_t because a 32-bit ms clock wraps after about 49.7 days. */
#define GT_HEALTH_OFFLINE_AFTER 10     /* consecutive failed reads -> offline */
#define GT_HEALTH_RETRY_MS      5000   /* probe period while offline */

typedef enum { GT_HEALTH_ONLINE, GT_HEALTH_OFFLINE } gt_health_state;

/* Returned by gt_health_record; the caller logs sensor_offline / sensor_online. */
typedef enum {
    GT_HEALTH_EV_NONE,
    GT_HEALTH_EV_OFFLINE,
    GT_HEALTH_EV_ONLINE
} gt_health_event;

typedef struct {
    gt_health_state state;
    uint32_t        consecutive_fails;
    uint64_t        next_probe_ms;     /* valid only while OFFLINE */
} gt_health;

void            gt_health_init(gt_health *health);
/* Online: always 1. Offline: 1 only once now_ms >= next_probe_ms. NULL -> 0. */
int             gt_health_should_read(const gt_health *health, uint64_t now_ms);
/* Feed one read result; any non-GT_OK is a failure (a failed gt_light_read
 * already includes the driver's retries). NULL -> GT_HEALTH_EV_NONE. */
gt_health_event gt_health_record(gt_health *health, gt_status read_result, uint64_t now_ms);

/* Log event names (DESIGN.md failure-mode table, Sensor (I2C) row).
 * i2c_read_error is logged on every failed read, not only on a transition. */
#define GT_HEALTH_I2C_READ_ERROR "i2c_read_error"
/* "sensor_offline" / "sensor_online"; NULL for GT_HEALTH_EV_NONE or an
 * unknown value (nothing to log). */
const char     *gt_health_event_name(gt_health_event event);

#endif
