/* BH1750 ambient light sensor driver (see light_sensor.h).
 *
 * Purpose: speaks the BH1750 protocol over the gt_i2c_ops seam: power-on and
 * mode select at open, a 2-byte measurement read, and the read retry policy
 * from DESIGN.md's failure-mode table ("Retry 3x at 10 ms, then skip").
 * It makes no system calls itself; all bus traffic and waits go through
 * bus.ops, so tests can run every path against a fake bus.
 *
 * Device model: after POWER_ON + CONT_HRES the chip measures continuously
 * (high-res, 1 lx/count, <= 180 ms per conversion) and each 2-byte read
 * returns the latest result, high byte first. Lux = count / 1.2. The driver
 * returns the raw count; conversion happens downstream.
 *
 * Not here: offline/online tracking after repeated failures. That belongs to
 * the light_sensor process, which sees the run of consecutive errors. */
#include "light_sensor.h"

#include <stdlib.h>

struct gt_light_sensor {
    gt_i2c_bus bus;
};

/* Send a one-byte BH1750 opcode. */
static gt_status send_cmd(gt_light_sensor *s, uint8_t op)
{
    return s->bus.ops->write(s->bus.ctx, &op, 1);
}

/* Open the BH1750 on the Linux bus `i2c_dev` at GT_LIGHT_I2C_ADDR.
 * Returns NULL if the bus cannot be opened or the device does not respond. */
gt_light_sensor *gt_light_open(const char *i2c_dev)
{
    gt_i2c_bus bus;
    if (gt_i2c_linux_open(i2c_dev, GT_LIGHT_I2C_ADDR, &bus) != GT_OK) {
        return NULL;
    }
    return gt_light_open_bus(bus);
}

/* Initialise the device on an already-open bus: power on, reset the data
 * register, start continuous high-res mode, then wait one worst-case
 * conversion so the first read returns real data. The power-on write is the
 * first point where a missing device shows up (no ACK -> GT_ERR_IO).
 * Takes ownership of `bus`: on any failure the bus is closed and NULL is
 * returned, so the caller never has to clean up. */
gt_light_sensor *gt_light_open_bus(gt_i2c_bus bus)
{
    if (bus.ops == NULL) {
        return NULL;
    }

    gt_light_sensor *s = malloc(sizeof *s);
    if (s == NULL) {
        bus.ops->close(bus.ctx);
        return NULL;
    }
    s->bus = bus;

    if (send_cmd(s, GT_BH1750_POWER_ON) != GT_OK ||
        send_cmd(s, GT_BH1750_RESET) != GT_OK ||
        send_cmd(s, GT_BH1750_CONT_HRES) != GT_OK) {
        bus.ops->close(bus.ctx);
        free(s);
        return NULL;
    }

    bus.ops->sleep_ms(bus.ctx, GT_BH1750_MEAS_MAX_MS);
    return s;
}

/* Read the latest measurement as a raw 16-bit count into `raw_out`.
 * A failed read is retried up to GT_LIGHT_RETRIES times, GT_LIGHT_RETRY_GAP_MS
 * apart; if every attempt fails, returns GT_ERR_IO and leaves `raw_out`
 * untouched so the caller can skip the sample. GT_ERR_INVAL on NULL args. */
gt_status gt_light_read(gt_light_sensor *s, uint32_t *raw_out)
{
    if (s == NULL || raw_out == NULL) {
        return GT_ERR_INVAL;
    }

    uint8_t b[2];
    for (int attempt = 0; attempt <= GT_LIGHT_RETRIES; attempt++) {
        if (attempt > 0) {
            s->bus.ops->sleep_ms(s->bus.ctx, GT_LIGHT_RETRY_GAP_MS);
        }
        if (s->bus.ops->read(s->bus.ctx, b, sizeof b) == GT_OK) {
            *raw_out = ((uint32_t)b[0] << 8) | b[1];
            return GT_OK;
        }
    }
    return GT_ERR_IO;
}

/* Power the device down (best effort: an unplugged sensor must still close
 * cleanly), then release the bus and the driver state. NULL-safe. */
void gt_light_close(gt_light_sensor *s)
{
    if (s == NULL) {
        return;
    }
    (void)send_cmd(s, GT_BH1750_POWER_DOWN);
    s->bus.ops->close(s->bus.ctx);
    free(s);
}
#ifndef FAKE_I2C_H
#define FAKE_I2C_H

/* Fake gt_i2c_ops for driver tests: no /dev/i2c-1, no real sleeping.
 *
 * A test declares a fake_i2c on the stack, scripts read data and failures,
 * passes fake_i2c_bus(&f) to the driver, then inspects what the driver did:
 * bytes written, read attempts, waits and closes. The fake is the bus ctx
 * and is owned by the test, so close() only counts and never frees.
 * fake_i2c_bus() zeroes the fake, so call it before scripting anything.
 *
 * Header-only (static inline) because the Makefile links each test .c with
 * src/ only; inline keeps unused helpers from tripping -Werror. */
#include <stddef.h>
#include <stdint.h>
#include <string.h>

#include "i2c_bus.h"

#define FAKE_I2C_MAX_WRITTEN 64
#define FAKE_I2C_MAX_READ    64

typedef struct {
    /* Every attempted write, in order (failed ones too: the bus was driven). */
    uint8_t  written[FAKE_I2C_MAX_WRITTEN];
    size_t   n_written;
    int      write_calls;

    /* Scripted read data, consumed front to back across read() calls. */
    uint8_t  read_data[FAKE_I2C_MAX_READ];
    size_t   n_read_data;
    size_t   read_pos;
    int      read_calls;

    /* Failure injection: the next N calls of each kind return GT_ERR_IO. */
    int      fail_writes;
    int      fail_reads;
    /* Fail only the Nth write call (1-based, counted since fake_i2c_bus);
     * 0 = off. Lets a test pass the first commands and NACK a later one. */
    int      fail_write_at;

    int      sleep_calls;
    uint32_t slept_ms_total;
    int      closed;
} fake_i2c;

/* Append `len` bytes to the data later reads will return. */
static inline void fake_i2c_push_read(fake_i2c *f, const uint8_t *buf, size_t len)
{
    for (size_t i = 0; i < len && f->n_read_data < FAKE_I2C_MAX_READ; i++) {
        f->read_data[f->n_read_data++] = buf[i];
    }
}

static inline gt_status fake_i2c_write(void *ctx, const uint8_t *buf, size_t len)
{
    fake_i2c *f = ctx;
    f->write_calls++;
    for (size_t i = 0; i < len && f->n_written < FAKE_I2C_MAX_WRITTEN; i++) {
        f->written[f->n_written++] = buf[i];
    }
    if (f->fail_writes > 0) {
        f->fail_writes--;
        return GT_ERR_IO;
    }
    if (f->fail_write_at == f->write_calls) {
        return GT_ERR_IO;
    }
    return GT_OK;
}

/* A failed read consumes no data. Running out of scripted data is a short
 * read, which the real bus also reports as GT_ERR_IO. */
static inline gt_status fake_i2c_read(void *ctx, uint8_t *buf, size_t len)
{
    fake_i2c *f = ctx;
    f->read_calls++;
    if (f->fail_reads > 0) {
        f->fail_reads--;
        return GT_ERR_IO;
    }
    if (f->n_read_data - f->read_pos < len) {
        return GT_ERR_IO;
    }
    memcpy(buf, &f->read_data[f->read_pos], len);
    f->read_pos += len;
    return GT_OK;
}

static inline void fake_i2c_sleep_ms(void *ctx, uint32_t ms)
{
    fake_i2c *f = ctx;
    f->sleep_calls++;
    f->slept_ms_total += ms;
}

static inline void fake_i2c_close(void *ctx)
{
    fake_i2c *f = ctx;
    f->closed++;
}

/* Reset `f` and return a bus that routes every op to it. */
static inline gt_i2c_bus fake_i2c_bus(fake_i2c *f)
{
    static const gt_i2c_ops ops = {
        .write    = fake_i2c_write,
        .read     = fake_i2c_read,
        .sleep_ms = fake_i2c_sleep_ms,
        .close    = fake_i2c_close,
    };
    memset(f, 0, sizeof *f);
    return (gt_i2c_bus){ .ops = &ops, .ctx = f };
}

#endif
