        return GT_ERR_INVAL;
    }

    linux_i2c *b = malloc(sizeof *b);
    if (b == NULL) {
        return GT_ERR_NOMEM;
    }

    b->fd = open(dev, O_RDWR);
    if (b->fd < 0) {
        free(b);
        return GT_ERR_IO;
    }

