    if (ioctl(b->fd, I2C_SLAVE, (unsigned long)addr) < 0) {
        close(b->fd);
        free(b);
        return GT_ERR_IO;
    }

    out->ops = &linux_ops;
    out->ctx = b;
    return GT_OK;
}
