        GT_SEESAW_STATUS_BASE, GT_SEESAW_STATUS_HW_ID,
    };
    CHECK_EQ(f.n_written, sizeof expected);
    for (size_t byte_index = 0; byte_index < sizeof expected; byte_index++) {
        CHECK_EQ(f.written[byte_index], expected[byte_index]);
