    const uint8_t hw_id[] = { GT_SEESAW_HW_ID_CODE };
    fake_i2c_push_read(f, hw_id, sizeof hw_id);
    return gt_soil_open_bus(bus);
}

/* ---- SSC-01: close releases the bus once and sends nothing ---- */
