128	/* Sleep until absolute CLOCK_MONOTONIC time `us`. Absolute deadlines keep
129	 * the schedule from drifting: a late wake-up doesn't push later samples
130	 * back, as a relative sleep(period) after each read would. */
131	static void sleep_until_us(int64_t us)
132	{
133	    struct timespec t = { .tv_sec = us / 1000000, .tv_nsec = (long)(us % 1000000) * 1000 };
134	    /* clock_nanosleep returns the error number itself, not -1/errno. */
135	    while (clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &t, NULL) == EINTR) {
136	    }
