145	/* Nearest-rank percentile of a sorted array, e.g. pct = 99. */
146	static int64_t percentile(const int64_t *sorted, int n, int pct)
147	{
148	    int rank = (pct * n + 99) / 100;   /* ceil(pct/100 * n) */
149	    return sorted[rank > 0 ? rank - 1 : 0];
150	}
