156	    int64_t  ivl_min, ivl_max, ivl_sum;
157	    uint32_t raw_min, raw_max;   /* over successful reads only */
158	    double   lux_sum;
159	    int      errors, good;       /* failed / successful reads */
160	} sample_stats;
