183	        stats->ivl_min = interval_us < stats->ivl_min ? interval_us : stats->ivl_min;
184	        stats->ivl_max = interval_us > stats->ivl_max ? interval_us : stats->ivl_max;
185	        stats->ivl_sum += interval_us;
186	    }
