213	    int64_t p99 = percentile(sorted_dev_us, sample_count, 99);
214	    int64_t dev_max = sorted_dev_us[sample_count - 1];
215	
216	    printf("      reads:    %d ok, %d failed\n", stats->good, stats->errors);
217	    if (stats->good > 0) {
218	        printf("      lux:      min %.1f  mean %.1f  max %.1f\n",
219	               gt_light_raw_to_lux(stats->raw_min), stats->lux_sum / stats->good,
220	               gt_light_raw_to_lux(stats->raw_max));
221	    }
222	    printf("      interval: min %.3f  mean %.3f  max %.3f ms (target %ld)\n",
223	           stats->ivl_min / 1000.0, stats->ivl_sum / 1000.0 / (sample_count - 1),
224	           stats->ivl_max / 1000.0, period_ms);
225	    printf("      jitter:   p50 %lld  p99 %lld  max %lld us (p99 limit %d)\n",
