237	 * Each sample is timestamped just before its I2C read, which is the point
238	 * DESIGN.md measures jitter at. Prints every sample so lux can be watched
239	 * live (cover the sensor, shine a light), then a summary. Passes if every
240	 * read succeeded and p99 deviation from the schedule is under 10 ms. */
241	static int check_sampling(gt_light_sensor *s, int n, long period_ms)
242	{
243	    int64_t *dev_us = malloc((size_t)n * sizeof *dev_us);
244	    if (dev_us == NULL) {
245	        report(4, "sampling interval", 0);
246	        return 0;
247	    }
248	
249	    int64_t period_us = (int64_t)period_ms * 1000;
250	    int64_t start = mono_us() + period_us;
251	    sample_stats stats;
252	    init_sample_stats(&stats);
253	
254	    printf("      sampling %d x %ld ms (cover the sensor / shine a light to see lux follow)\n",
255	           n, period_ms);
256	    printf("      %4s %10s %7s %9s %8s\n", "i", "t_ms", "raw", "lux", "dev_us");
257	
258	    for (int i = 0; i < n; i++) {
259	        dev_us[i] = read_scheduled_sample(s, i, start, start + i * period_us, &stats);
260	    }
261	
262	    qsort(dev_us, (size_t)n, sizeof *dev_us, cmp_i64);
263	    int64_t p99 = percentile(dev_us, n, 99);
264	    int ok = stats.errors == 0 && p99 < JITTER_P99_LIMIT_US;
265	    report(4, "sampling interval", ok);
266	    print_sampling_summary(&stats, dev_us, n, period_ms);
267	    free(dev_us);
268	    return ok;
269	}
