 * failed. The first slot is at 0; returns the time of the last one. */
static uint64_t fail_slots(soil_harness *harness, int failures)
{
    uint64_t now_ms = 0;
    /* Invariant: slot_index reads have failed before this pass. */
    for (int slot_index = 0; slot_index < failures; slot_index++) {
        now_ms = (uint64_t)slot_index * HARNESS_PERIOD_MS;
