#ifndef SOIL_LOOP_HARNESS_H
#define SOIL_LOOP_HARNESS_H

/* Shared setup for the soil loop tests (tests/test_soil_loop_*.c): a loop
 * wired to a fake_i2c seesaw, a fake_sock hub, and a log capture.
 *
 * A test declares a soil_harness on the stack, calls harness_start, scripts
 * the seesaw (harness_push_raw, harness_fail_next_read) and the hub
 * (h.sock), ticks h.loop, then inspects h.sock.sent, h.logs and h.bus.i2c.
 * It ends with gt_soil_loop_destroy(h.loop). Everything lives in the
 * harness, which the test owns, so the fakes' close/destroy only count.
 *
 * Header-only (static inline) for the same reason as fake_i2c.h. */
#include <stddef.h>
#include <stdint.h>
#include <string.h>

#include "fake_i2c.h"
#include "fake_sock.h"
#include "ipc.h"
#include "ipc_sock.h"
#include "soil_loop.h"
#include "soil_sensor.h"

#define HARNESS_PERIOD_MS 60000u
#define HARNESS_LOG_MAX   64

/* Stands in for gt_i2c_linux_open: hands out the one fake bus, or fails
 * the next fail_opens calls as if /dev/i2c-1 couldn't be opened. */
typedef struct {
    fake_i2c   i2c;
    gt_i2c_bus bus;
    int        open_calls;
    int        fail_opens;
} fake_bus_opener;

/* Every event the loop logged, in order. */
typedef struct {
    gt_log_level level[HARNESS_LOG_MAX];
    char         event[HARNESS_LOG_MAX][32];
    char         fields[HARNESS_LOG_MAX][64];
    int          count;
} log_capture;

typedef struct {
    fake_bus_opener bus;
    fake_sock       sock;
    log_capture     logs;
    gt_soil_loop   *loop;
} soil_harness;

static inline gt_status harness_bus_open(void *ctx, gt_i2c_bus *bus_out)
{
    fake_bus_opener *opener = ctx;
    opener->open_calls++;
    if (opener->fail_opens > 0) {
        opener->fail_opens--;
        return GT_ERR_IO;
    }
    *bus_out = opener->bus;
    return GT_OK;
}

static inline void harness_log(void *ctx, gt_log_level level, const char *event,
                               const char *fields)
{
    log_capture *logs = ctx;
    if (logs->count >= HARNESS_LOG_MAX) {
        return;
    }
    logs->level[logs->count] = level;
    strncpy(logs->event[logs->count], event, sizeof logs->event[0] - 1);
    strncpy(logs->fields[logs->count], fields, sizeof logs->fields[0] - 1);
    logs->count++;
}

/* Script the seesaw's hardware-ID byte, consumed by one open or reinit. */
static inline void harness_push_hw_id(soil_harness *harness)
{
    const uint8_t hw_id[] = { GT_SEESAW_HW_ID_CODE };
    fake_i2c_push_read(&harness->bus.i2c, hw_id, sizeof hw_id);
}

/* Script one moisture reading, high byte first. */
static inline void harness_push_raw(soil_harness *harness, uint16_t raw)
{
    const uint8_t data[] = { (uint8_t)(raw >> 8), (uint8_t)(raw & 0xFF) };
    fake_i2c_push_read(&harness->bus.i2c, data, sizeof data);
}

/* Make the next gt_soil_read fail: every attempt, retries included. */
static inline void harness_fail_next_read(soil_harness *harness)
{
    harness->bus.i2c.fail_reads += 1 + GT_SOIL_RETRIES;
}

/* Zero the harness, script the ID byte the first open reads, and create a
 * loop with `period_ms` whose first reading is due at `now_ms`. */
static inline void harness_start(soil_harness *harness, uint32_t period_ms, uint64_t now_ms)
{
    memset(harness, 0, sizeof *harness);
    harness->bus.bus = fake_i2c_bus(&harness->bus.i2c);
    harness_push_hw_id(harness);
    gt_ipc_client *client = gt_ipc_client_open_ops(fake_sock_ops(&harness->sock),
                                                   &harness->sock);
    gt_soil_loop_cfg cfg = {
        .period_ms = period_ms,
        .bus_open = harness_bus_open, .bus_ctx = &harness->bus,
        .log = harness_log, .log_ctx = &harness->logs,
    };
    harness->loop = gt_soil_loop_create(&cfg, client, now_ms);
}

/* How many times `event` was logged. */
static inline int harness_count(const soil_harness *harness, const char *event)
{
    int matches = 0;
    for (int log_index = 0; log_index < harness->logs.count; log_index++) {
        matches += strcmp(harness->logs.event[log_index], event) == 0;
    }
    return matches;
}

/* Index of the first `event` logged, or -1 if it never was. */
static inline int harness_find(const soil_harness *harness, const char *event)
{
    for (int log_index = 0; log_index < harness->logs.count; log_index++) {
        if (strcmp(harness->logs.event[log_index], event) == 0) {
            return log_index;
        }
    }
    return -1;
}

/* Decode the hub's received frame number `sent_index` into *message_out.
 * GT_ERR_INVAL if there is no such frame. */
static inline gt_status harness_sent(const soil_harness *harness, size_t sent_index,
                                     gt_msg *message_out)
{
    if (sent_index >= harness->sock.n_sent) {
        return GT_ERR_INVAL;
    }
    return gt_msg_decode(harness->sock.sent[sent_index], message_out);
}

#endif

/* Unit tests for creating and destroying the soil loop (src/soil_loop.c):
 * gt_soil_loop_create, gt_soil_loop_destroy, and tick's NULL check.
 *
 * Purpose: prove create does no I/O, rejects a bad config without leaking
 * the client it was handed, and that destroy releases the sensor bus and
 * the client exactly once whether or not the sensor ever opened. Run under
 * make test / asan / memcheck, so leaks and double-closes also fail.
 * Implements SLC-01 through SLC-04. Sampling is test_soil_loop_sample.c,
 * health test_soil_loop_health.c, the hub side test_soil_loop_ipc.c. */
#include <stddef.h>

#include "check.h"
#include "soil_loop_harness.h"

/* ---- SLC-01: create does no I/O ----
 * No bus open and no hub connect until the first tick, so a process that
 * starts before the hub or with no sensor still starts. */
static void test_slc01_create_does_no_io(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);
    CHECK(harness.loop != NULL);
    CHECK_EQ(harness.bus.open_calls, 0);
    CHECK_EQ(harness.sock.connect_calls, 0);
    CHECK_EQ(harness.logs.count, 0);

    gt_soil_loop_destroy(harness.loop);
}

/* ---- SLC-02: a bad config is rejected, client still closed ----
 * create owns the client from the call on, so each rejection must destroy
 * it exactly once. A NULL client is rejected too. */
static void test_slc02_bad_config_rejected(void)
{
    fake_bus_opener opener = { .open_calls = 0 };
    log_capture logs = { .count = 0 };
    gt_soil_loop_cfg good = {
        .period_ms = HARNESS_PERIOD_MS,
        .bus_open = harness_bus_open, .bus_ctx = &opener,
        .log = harness_log, .log_ctx = &logs,
    };
    gt_soil_loop_cfg zero_period = good;
    zero_period.period_ms = 0;
    gt_soil_loop_cfg no_opener = good;
    no_opener.bus_open = NULL;
    gt_soil_loop_cfg no_log = good;
    no_log.log = NULL;
    const gt_soil_loop_cfg *bad_cfgs[] = { NULL, &zero_period, &no_opener, &no_log };

    /* Invariant: each pass hands create a fresh client on a freshly zeroed fake. */
    for (size_t cfg_index = 0; cfg_index < sizeof bad_cfgs / sizeof bad_cfgs[0]; cfg_index++) {
        fake_sock sock;
        gt_ipc_client *client = gt_ipc_client_open_ops(fake_sock_ops(&sock), &sock);
        CHECK(gt_soil_loop_create(bad_cfgs[cfg_index], client, 0) == NULL);
        CHECK_EQ(sock.destroy_calls, 1);
    }
    CHECK(gt_soil_loop_create(&good, NULL, 0) == NULL);
}

/* ---- SLC-03: destroy closes the open sensor and the client ---- */
static void test_slc03_destroy_closes_both(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);
    harness_push_raw(&harness, 400);
    CHECK_EQ(gt_soil_loop_tick(harness.loop, 0), GT_OK);
    CHECK_EQ(harness.bus.i2c.closed, 0);

    gt_soil_loop_destroy(harness.loop);
    CHECK_EQ(harness.bus.i2c.closed, 1);
    CHECK_EQ(harness.sock.destroy_calls, 1);
}

/* ---- SLC-04: never-opened sensor, NULL loop are safe ----
 * The sensor never opened: destroy closes only the client. destroy(NULL)
 * is a no-op and tick(NULL) is GT_ERR_INVAL. */
static void test_slc04_unopened_and_null_safe(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);
    harness.bus.fail_opens = 1;
    CHECK_EQ(gt_soil_loop_tick(harness.loop, 0), GT_OK);

    gt_soil_loop_destroy(harness.loop);
    CHECK_EQ(harness.bus.i2c.closed, 0);
    CHECK_EQ(harness.sock.destroy_calls, 1);

    gt_soil_loop_destroy(NULL);
    CHECK_EQ(gt_soil_loop_tick(NULL, 0), GT_ERR_INVAL);
}

static const test_case_t tests[] = {
    {"SLC-01", "create does no I/O", test_slc01_create_does_no_io},
    {"SLC-02", "bad config rejected, client still closed", test_slc02_bad_config_rejected},
    {"SLC-03", "destroy closes the open sensor and client", test_slc03_destroy_closes_both},
    {"SLC-04", "never-opened sensor, NULL loop are safe", test_slc04_unopened_and_null_safe},
};

int main(void)
{
    return RUN_TESTS(tests);
}

/* Unit tests for the soil loop's sampling schedule (src/soil_loop.c):
 * gt_soil_loop_tick taking and sending readings.
 *
 * Purpose: prove the first tick opens the seesaw and sends a reading, that
 * readings follow the period exactly (one per slot, however often tick is
 * called), that missed slots are skipped with sample_overrun instead of
 * read in a burst, and that a failed read sends nothing and doesn't use up
 * a counter. Runs against fake_i2c and fake_sock. Run under make test /
 * asan / memcheck. Implements SLS-01 through SLS-04.
 *
 * What these tests cannot prove: real timing jitter. That's the 100 ms
 * tick in src/soil_sensor_main.c, measured on the Pi. */
#include <stdint.h>
#include <string.h>

#include "check.h"
#include "soil_loop_harness.h"

/* ---- SLS-01: first tick opens, reads, sends the reading ----
 * The hub gets {DATA, SOIL, counter 0, seq 0, raw}: seq is 0 because only
 * the hub stamps it. */
static void test_sls01_first_tick_sends_reading(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);
    harness_push_raw(&harness, 400);

    CHECK_EQ(gt_soil_loop_tick(harness.loop, 0), GT_OK);
    CHECK_EQ(harness.bus.open_calls, 1);
    CHECK_EQ(harness.sock.n_sent, 1);

    gt_msg message;
    CHECK_EQ(harness_sent(&harness, 0, &message), GT_OK);
    CHECK_EQ(message.type, GT_MSG_DATA);
    CHECK_EQ(message.sensor_id, GT_SENSOR_SOIL);
    CHECK_EQ(message.counter, 0);
    CHECK_EQ(message.seq, 0);
    CHECK_EQ(message.value, 400);
    CHECK_EQ(harness.logs.count, 0);

    gt_soil_loop_destroy(harness.loop);
}

/* ---- SLS-02: one reading per period, however often tick runs ----
 * Ticking every 100 ms for two periods gives readings at 0, 60 s and
 * 120 s only, with counters 0, 1, 2. */
static void test_sls02_one_reading_per_period(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);
    harness_push_raw(&harness, 300);
    harness_push_raw(&harness, 500);
    harness_push_raw(&harness, 700);

    /* Invariant: after the tick at now_ms, one reading per slot <= now_ms was sent. */
    for (uint64_t now_ms = 0; now_ms <= 2 * HARNESS_PERIOD_MS; now_ms += 100) {
        CHECK_EQ(gt_soil_loop_tick(harness.loop, now_ms), GT_OK);
        if (now_ms == HARNESS_PERIOD_MS - 100) {
            CHECK_EQ(harness.sock.n_sent, 1);
        }
    }
    CHECK_EQ(harness.sock.n_sent, 3);

    const uint32_t expected_raw[] = { 300, 500, 700 };
    for (size_t sent_index = 0; sent_index < 3; sent_index++) {
        gt_msg message;
        CHECK_EQ(harness_sent(&harness, sent_index, &message), GT_OK);
        CHECK_EQ(message.counter, sent_index);
        CHECK_EQ(message.value, expected_raw[sent_index]);
    }

    gt_soil_loop_destroy(harness.loop);
}

/* ---- SLS-03: missed slots are skipped, not read in a burst ----
 * The process stalls from 0 to 190 s: the 60 s and 120 s slots are gone.
 * One reading is taken for the 180 s slot, sample_overrun logs
 * skipped=2, and the schedule stays anchored (next reading at 240 s). */
static void test_sls03_overrun_skips_missed_slots(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);
    harness_push_raw(&harness, 300);
    harness_push_raw(&harness, 500);
    harness_push_raw(&harness, 700);

    CHECK_EQ(gt_soil_loop_tick(harness.loop, 0), GT_OK);
    CHECK_EQ(gt_soil_loop_tick(harness.loop, 190000), GT_OK);
    CHECK_EQ(harness.sock.n_sent, 2);
    CHECK_EQ(harness_count(&harness, "sample_overrun"), 1);
    int overrun = harness_find(&harness, "sample_overrun");
    CHECK(overrun >= 0 && strcmp(harness.logs.fields[overrun], "skipped=2") == 0);

    CHECK_EQ(gt_soil_loop_tick(harness.loop, 239999), GT_OK);
    CHECK_EQ(harness.sock.n_sent, 2);
    CHECK_EQ(gt_soil_loop_tick(harness.loop, 240000), GT_OK);
    CHECK_EQ(harness.sock.n_sent, 3);

    gt_msg message;
    CHECK_EQ(harness_sent(&harness, 2, &message), GT_OK);
    CHECK_EQ(message.counter, 2);   /* skipped slots use no counter */

    gt_soil_loop_destroy(harness.loop);
}

/* ---- SLS-04: a failed read sends nothing, keeps the counter ----
 * i2c_read_error is logged; the next good reading is still counter 0, so
 * the hub sees no counter gap for a reading that never existed. */
static void test_sls04_failed_read_sends_nothing(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);
    harness_fail_next_read(&harness);

    CHECK_EQ(gt_soil_loop_tick(harness.loop, 0), GT_OK);
    CHECK_EQ(harness.sock.n_sent, 0);
    CHECK_EQ(harness_count(&harness, GT_HEALTH_I2C_READ_ERROR), 1);

    harness_push_raw(&harness, 450);
    CHECK_EQ(gt_soil_loop_tick(harness.loop, HARNESS_PERIOD_MS), GT_OK);
    gt_msg message;
    CHECK_EQ(harness_sent(&harness, 0, &message), GT_OK);
    CHECK_EQ(message.counter, 0);
    CHECK_EQ(message.value, 450);

    gt_soil_loop_destroy(harness.loop);
}

static const test_case_t tests[] = {
    {"SLS-01", "first tick opens, reads, sends the reading",
     test_sls01_first_tick_sends_reading},
    {"SLS-02", "one reading per period", test_sls02_one_reading_per_period},
    {"SLS-03", "missed slots skipped, not read in a burst",
     test_sls03_overrun_skips_missed_slots},
    {"SLS-04", "failed read sends nothing, keeps counter",
     test_sls04_failed_read_sends_nothing},
};

int main(void)
{
    return RUN_TESTS(tests);
}

/* Unit tests for the soil loop's failure handling (src/soil_loop.c):
 * offline/online, re-init after a replug, and a sensor missing at startup.
 *
 * Purpose: prove the DESIGN.md failure-mode rows for a sensor. 10 failed
 * reads in a row mark it offline; while offline it is probed with
 * gt_soil_reinit every 5 s instead of read on the 60 s schedule; a probe
 * that succeeds logs sensor_reinit then sensor_online and readings resume;
 * and a sensor that can't be opened at startup doesn't stop the process,
 * it starts offline and is retried every 5 s. Runs against fake_i2c and
 * fake_sock. Run under make test / asan / memcheck.
 * Implements SLH-01 through SLH-04.
 *
 * What these tests cannot prove: that a real replugged board answers the
 * reinit. That needs the Pi (pull the STEMMA cable). */
#include <stdint.h>

#include "check.h"
#include "soil_loop_harness.h"

/* Tick once per slot, each read failing, until `failures` reads have
 * failed. The first slot is at 0; returns the time of the last one. */
static uint64_t fail_slots(soil_harness *harness, int failures)
{
    uint64_t now_ms = 0;
    /* Invariant: slot_index reads have failed before this pass. */
    for (int slot_index = 0; slot_index < failures; slot_index++) {
        now_ms = (uint64_t)slot_index * HARNESS_PERIOD_MS;
        harness_fail_next_read(harness);
        gt_soil_loop_tick(harness->loop, now_ms);
    }
    return now_ms;
}

/* ---- SLH-01: offline only on the 10th failure in a row ----
 * 9 failures log i2c_read_error each but stay online; the 10th logs
 * sensor_offline, once. */
static void test_slh01_offline_after_ten_failures(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);

    fail_slots(&harness, GT_HEALTH_OFFLINE_AFTER - 1);
    CHECK_EQ(harness_count(&harness, "sensor_offline"), 0);
    CHECK_EQ(harness_count(&harness, GT_HEALTH_I2C_READ_ERROR), GT_HEALTH_OFFLINE_AFTER - 1);

    harness_fail_next_read(&harness);
    gt_soil_loop_tick(harness.loop, (uint64_t)(GT_HEALTH_OFFLINE_AFTER - 1) * HARNESS_PERIOD_MS);
    CHECK_EQ(harness_count(&harness, "sensor_offline"), 1);
    CHECK_EQ(harness.sock.n_sent, 0);

    gt_soil_loop_destroy(harness.loop);
}

/* ---- SLH-02: offline: probed every 5 s, not read on schedule ----
 * A probe is a reinit (reset + ID check). A failed probe tries again 5 s
 * later; a slot that comes due while offline takes no reading. */
static void test_slh02_offline_probes_every_5s(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);
    uint64_t offline_at = fail_slots(&harness, GT_HEALTH_OFFLINE_AFTER);
    int reads_when_offline = harness.bus.i2c.read_calls;
    int writes_when_offline = harness.bus.i2c.write_calls;

    /* Still unplugged: every write is NACKed, so each probe fails at the reset. */
    harness.bus.i2c.fail_writes = 1000;
    gt_soil_loop_tick(harness.loop, offline_at + GT_HEALTH_RETRY_MS - 100);
    CHECK_EQ(harness.bus.i2c.write_calls, writes_when_offline);
    gt_soil_loop_tick(harness.loop, offline_at + GT_HEALTH_RETRY_MS);
    CHECK_EQ(harness.bus.i2c.write_calls, writes_when_offline + 1);
    gt_soil_loop_tick(harness.loop, offline_at + 2 * GT_HEALTH_RETRY_MS - 100);
    CHECK_EQ(harness.bus.i2c.write_calls, writes_when_offline + 1);
    gt_soil_loop_tick(harness.loop, offline_at + 2 * GT_HEALTH_RETRY_MS);
    CHECK_EQ(harness.bus.i2c.write_calls, writes_when_offline + 2);

    /* The next slot comes due while offline: no moisture read is attempted. */
    gt_soil_loop_tick(harness.loop, offline_at + HARNESS_PERIOD_MS);
    CHECK_EQ(harness.bus.i2c.read_calls, reads_when_offline);
    CHECK_EQ(harness.sock.n_sent, 0);
    CHECK_EQ(harness_count(&harness, "sensor_online"), 0);

    gt_soil_loop_destroy(harness.loop);
}

/* ---- SLH-03: a good probe reinits, goes online, reads resume ----
 * Replugged: the probe's reinit succeeds, sensor_reinit is logged before
 * sensor_online, and the next slot's reading reaches the hub. */
static void test_slh03_replug_reinits_then_online(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);
    uint64_t offline_at = fail_slots(&harness, GT_HEALTH_OFFLINE_AFTER);

    harness_push_hw_id(&harness);
    gt_soil_loop_tick(harness.loop, offline_at + GT_HEALTH_RETRY_MS);
    int reinit = harness_find(&harness, "sensor_reinit");
    int online = harness_find(&harness, "sensor_online");
    CHECK(reinit >= 0);
    CHECK(online > reinit);
    CHECK_EQ(harness.sock.n_sent, 0);

    harness_push_raw(&harness, 820);
    gt_soil_loop_tick(harness.loop, offline_at + HARNESS_PERIOD_MS);
    CHECK_EQ(harness.sock.n_sent, 1);
    gt_msg message;
    CHECK_EQ(harness_sent(&harness, 0, &message), GT_OK);
    CHECK_EQ(message.value, 820);

    gt_soil_loop_destroy(harness.loop);
}

/* ---- SLH-04: open failing at startup: offline, retried 5 s ----
 * No exit (that would be a restart storm): i2c_open_error and
 * sensor_offline are logged, the open is retried every 5 s, and once it
 * works sensor_online is logged and the next slot is read. */
static void test_slh04_open_failure_retried(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);
    harness.bus.fail_opens = 2;

    gt_soil_loop_tick(harness.loop, 0);
    CHECK_EQ(harness.bus.open_calls, 1);
    CHECK_EQ(harness_count(&harness, "i2c_open_error"), 1);
    CHECK_EQ(harness_count(&harness, "sensor_offline"), 1);

    gt_soil_loop_tick(harness.loop, GT_HEALTH_RETRY_MS - 100);
    CHECK_EQ(harness.bus.open_calls, 1);
    gt_soil_loop_tick(harness.loop, GT_HEALTH_RETRY_MS);
    CHECK_EQ(harness.bus.open_calls, 2);
    CHECK_EQ(harness_count(&harness, "i2c_open_error"), 2);
    CHECK_EQ(harness_count(&harness, "sensor_offline"), 1);   /* not repeated */

    gt_soil_loop_tick(harness.loop, 2 * GT_HEALTH_RETRY_MS);
    CHECK_EQ(harness.bus.open_calls, 3);
    CHECK_EQ(harness_count(&harness, "sensor_online"), 1);
    CHECK_EQ(harness.sock.n_sent, 0);

    harness_push_raw(&harness, 390);
    gt_soil_loop_tick(harness.loop, HARNESS_PERIOD_MS);
    CHECK_EQ(harness.sock.n_sent, 1);
    gt_msg message;
    CHECK_EQ(harness_sent(&harness, 0, &message), GT_OK);
    CHECK_EQ(message.counter, 0);

    gt_soil_loop_destroy(harness.loop);
}

static const test_case_t tests[] = {
    {"SLH-01", "offline only on the 10th failure in a row",
     test_slh01_offline_after_ten_failures},
    {"SLH-02", "offline: probed every 5 s, not on schedule",
     test_slh02_offline_probes_every_5s},
    {"SLH-03", "good probe reinits, online, reads resume",
     test_slh03_replug_reinits_then_online},
    {"SLH-04", "open failing at startup: offline, retried",
     test_slh04_open_failure_retried},
};

int main(void)
{
    return RUN_TESTS(tests);
}

/* Unit tests for the soil loop's hub side (src/soil_loop.c): readings
 * reaching the hub through the IPC client while the hub comes and goes.
 *
 * Purpose: prove a reading taken while the hub is down is kept and
 * delivered by a later tick's pump (with no new reading due), and that
 * the client's disconnect / reconnect events are logged as ipc_disconnect
 * and ipc_reconnect. Runs against fake_i2c and fake_sock. Run under make
 * test / asan / memcheck. Implements SLI-01 and SLI-02.
 *
 * Not here: ring overflow and the GAP message. The client's own tests
 * (test_ipc_overflow.c) cover them, and 65 scripted readings don't fit in
 * fake_i2c's 64-byte read script. */
#include <stdint.h>

#include "check.h"
#include "soil_loop_harness.h"

/* ---- SLI-01: hub down: reading kept, pump delivers it later ----
 * The first connect fails, so the reading waits in the ring. 100 ms later
 * (the first backoff) a tick with no reading due connects and sends it,
 * and ipc_reconnect is logged because a failed attempt came before. */
static void test_sli01_pump_delivers_buffered(void)
{
    soil_harness harness;
    harness_start(&harness, HARNESS_PERIOD_MS, 0);
    harness_push_raw(&harness, 400);
    harness.sock.fail_connects = 1;

    CHECK_EQ(gt_soil_loop_tick(harness.loop, 0), GT_OK);
    CHECK_EQ(harness.sock.n_sent, 0);

    CHECK_EQ(gt_soil_loop_tick(harness.loop, GT_IPC_BACKOFF_MIN_MS), GT_OK);
    CHECK_EQ(harness.sock.n_sent, 1);
    CHECK_EQ(harness_count(&harness, "ipc_reconnect"), 1);
    gt_msg message;
    CHECK_EQ(harness_sent(&harness, 0, &message), GT_OK);
    CHECK_EQ(message.value, 400);

    gt_soil_loop_destroy(harness.loop);
}

/* ---- SLI-02: hub lost and back: disconnect, reconnect logged ----
