 * more than one can be logged from the same call. */
static void log_ipc_events(const gt_soil_loop *loop, unsigned events)
{
    if (events & GT_IPC_EV_DISCONNECT) {
        log_event(loop, GT_LOG_WARN, "ipc_disconnect", NULL);
