    if (events & GT_IPC_EV_RECONNECT) {
        log_event(loop, GT_LOG_INFO, "ipc_reconnect", NULL);
    }
    if (events & GT_IPC_EV_OVERFLOW) {
        gt_ipc_stats stats = { 0 };
        char fields[32];
        gt_ipc_client_stats(loop->client, &stats);
